function mount(render){
  function draw(){
    var m = (appsmith && appsmith.model) || {};
    try { document.getElementById('root').innerHTML = render(m); }
    catch(e){ document.getElementById('root').innerHTML =
      '<div class="empty">Could not render this view: '+esc(e.message)+'</div>'; }
