.queue-row small{display:block;color:var(--muted)}
.alert{font-size:15px}
.note{color:var(--muted);font-size:10px;margin-top:8px}
.gap{background:rgba(251,191,36,.08);border:1px dashed rgba(251,191,36,.45);border-radius:7px;padding:8px 10px;color:#fcd34d;font-size:11px;margin-top:8px}
.gap b{display:block;margin-bottom:2px}
.empty{padding:38px;text-align:center;color:var(--muted)}
.mapwrap{position:relative;height:285px;border-radius:7px;overflow:hidden;background:linear-gradient(140deg,#16233a,#111c2f);border:1px solid var(--line)}
.pin{position:absolute;border:2px solid #0f172a;background:var(--blue);border-radius:50%;box-shadow:0 2px 8px rgba(0,0,0,.6);transform:translate(-50%,-50%)}
.title-row{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:13px}
.title-row h1{font-size:22px;margin:0;color:var(--ink2)}
.title-row p{margin:3px 0 0;color:var(--muted)}
.title-row small{color:var(--muted);white-space:nowrap}
.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin-bottom:12px}
.tabs button{border:0;background:transparent;padding:9px 12px;color:var(--muted);border-bottom:2px solid transparent;cursor:pointer;font:inherit}
.tabs button:hover{color:var(--ink)}
.tabs button.active{color:var(--blue);border-color:var(--blue);font-weight:650}
select.btn{border:1px solid var(--line);background:var(--card2);color:var(--ink);border-radius:7px;padding:6px 9px;font:inherit;cursor:pointer}
.btn{border:1px solid var(--line);background:var(--card2);color:var(--ink);border-radius:7px;padding:7px 10px;cursor:pointer;font:inherit}
.cell{display:grid;place-items:center;font-size:10px;color:#0f172a;font-weight:700}
.estimated{background:#a78bfa}

