      var bh = (v/mx)*(y1-y0), y = y1-acc-bh; acc += bh;
      out += '<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+bw.toFixed(1)+
             '" height="'+Math.max(0.5,bh).toFixed(1)+'" fill="'+s.color+'"/>';
    });
  });
  out += axisLabels(labels, x0+slot/2, slot, y1, w, mx, y0);
  return out+'</svg>';
}

/* Columns + an overlaid line on its own scale — the charges-vs-consumption pairing. */
function comboChart(labels, bars, line, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!labels.length) return '<div class="empty">No data in this window</div>';
  var mb = scale(bars.values), ml = scale(line.values);
  var slot = (x1-x0)/labels.length, bw = Math.max(3, Math.min(26, slot*0.6));
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  labels.forEach(function(_,i){
    var v = Number(bars.values[i])||0;
    var bh = (v/mb)*(y1-y0), x = x0+slot*i+(slot-bw)/2;
    out += '<rect x="'+x.toFixed(1)+'" y="'+(y1-bh).toFixed(1)+'" width="'+bw.toFixed(1)+
           '" height="'+Math.max(0.5,bh).toFixed(1)+'" fill="'+bars.color+'" opacity=".75"/>';
  });
  var d='', started=false;
  line.values.forEach(function(v,i){
    if(v==null||!isFinite(v)){ started=false; return; }
    var x = x0+slot*i+slot/2, y = y1-(v/ml)*(y1-y0);
    d += (started?'L':'M')+x.toFixed(1)+' '+y.toFixed(1); started=true;
  });
  if(d) out += '<path d="'+d+'" fill="none" stroke="'+line.color+'" stroke-width="2.5"/>';
  out += axisLabels(labels, x0+slot/2, slot, y1, w, mb, y0);
  return out+'</svg>';
}

/* Actual line, forecast dashes and a confidence band. */
function forecastChart(points, h){
  h = h||230; var w=760, x0=44, y0=14, y1=h-30, x1=w-10;
  if(!points.length) return '<div class="empty">No data in this window</div>';
  var mx = scale(points.map(function(p){ return p.high!=null?p.high:p.charges; }));
  var step = points.length>1 ? (x1-x0)/(points.length-1) : 0;
  var X = function(i){ return x0+step*i; }, Y = function(v){ return y1-(v/mx)*(y1-y0); };
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

  var band = points.map(function(p,i){ return p.forecast&&p.high!=null?{i:i,p:p}:null; }).filter(Boolean);
  if(band.length>1){
    var up = band.map(function(b){ return X(b.i).toFixed(1)+' '+Y(b.p.high).toFixed(1); });
    var dn = band.slice().reverse().map(function(b){ return X(b.i).toFixed(1)+' '+Y(b.p.low).toFixed(1); });
    out += '<path d="M'+up.join('L')+'L'+dn.join('L')+'Z" fill="'+C.band+'"/>';
  }
  ['actual','forecast'].forEach(function(kind){
    var d='', started=false;
    points.forEach(function(p,i){
      var mine = kind==='actual' ? !p.forecast : p.forecast;
      /* join the two runs by letting the forecast start at the last actual point */
      if(kind==='forecast' && !p.forecast && points[i+1] && points[i+1].forecast) mine = true;
      if(!mine){ started=false; return; }
      d += (started?'L':'M')+X(i).toFixed(1)+' '+Y(p.charges).toFixed(1); started=true;
    });
    if(d) out += '<path d="'+d+'" fill="none" stroke="'+C.blue+'" stroke-width="2.5"'+
                 (kind==='forecast'?' stroke-dasharray="6 5"':'')+'/>';
  });
  out += axisLabels(points.map(function(p){return p.label;}), x0, step, y1, w, mx, y0);
  return out+'</svg>';
}

/* Scatter with an optional least-squares line. */
function scatterChart(points, fit, h, xlab, ylab){
  h = h||210; var w=560, x0=46, y0=12, y1=h-28, x1=w-12;
  if(!points.length) return '<div class="empty">Not enough data to plot</div>';
  var xs = points.map(function(p){return p.x;}), ys = points.map(function(p){return p.y;});
  var xmin=Math.min.apply(null,xs), xmax=Math.max.apply(null,xs);
  var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
  if(xmax===xmin) xmax=xmin+1; if(ymax===ymin) ymax=ymin+1;
  var X=function(v){ return x0+(v-xmin)/(xmax-xmin)*(x1-x0); };
  var Y=function(v){ return y1-(v-ymin)/(ymax-ymin)*(y1-y0); };

  var out = '<svg class="chart" viewBox="0 0 '+w+' '+h+'">' + gridLines(x0,y0,y1,x1,3);
  if(fit){
    var a=X(xmin), b=Y(fit.intercept+fit.slope*xmin), c=X(xmax), d=Y(fit.intercept+fit.slope*xmax);
    out += '<line x1="'+a.toFixed(1)+'" y1="'+b.toFixed(1)+'" x2="'+c.toFixed(1)+'" y2="'+d.toFixed(1)+
           '" stroke="'+C.teal+'" stroke-width="2"/>';
  }
  points.forEach(function(p){
    out += '<circle cx="'+X(p.x).toFixed(1)+'" cy="'+Y(p.y).toFixed(1)+'" r="3.5" fill="'+C.blue+'" opacity=".75"><title>'+
           esc((p.label||p.location||'')+' — '+num(p.x)+' / '+num(p.y))+'</title></circle>';
  });
  out += '<text x="'+(x0+(x1-x0)/2)+'" y="'+(h-4)+'" font-size="10" fill="'+C.axis+'" text-anchor="middle">'+esc(xlab||'')+'</text>';
  out += '<text x="6" y="'+(y0+8)+'" font-size="10" fill="'+C.axis+'">'+esc(ylab||'')+'</text>';
  return out+'</svg>';
}

/* Donut built from stroked arcs, with the total in the middle. */
function donut(items, centre){
  var total = items.reduce(function(a,i){ return a+Math.abs(i.charges!=null?i.charges:i.count); },0);
  if(!total) return '<div class="empty">No data</div>';
  var r=54, cx=70, cy=70, circ=2*Math.PI*r, off=0;
  var out='<svg viewBox="0 0 140 140" style="width:140px;height:140px;display:block;margin:auto">';
  items.forEach(function(it,i){
    var v = Math.abs(it.charges!=null?it.charges:it.count);
    var frac = v/total, len = frac*circ;
    out += '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+SERIES[i%SERIES.length]+
           '" stroke-width="20" stroke-dasharray="'+len.toFixed(2)+' '+(circ-len).toFixed(2)+
           '" stroke-dashoffset="'+(-off).toFixed(2)+'" transform="rotate(-90 '+cx+' '+cy+')"><title>'+
           esc((it.name||it.code)+' '+pct(frac*100))+'</title></circle>';
    off += len;
  });
  out += '<text x="'+cx+'" y="'+(cy+5)+'" text-anchor="middle" font-size="15" font-weight="700" fill="'+C.ink+'">'+esc(centre||'')+'</text>';
  return out+'</svg>';
}

function legend(items){
  return '<div class="legend">' + items.map(function(it,i){
    return '<span><i class="dot" style="background:'+(it.color||SERIES[i%SERIES.length])+'"></i>'+esc(it.name)+'</span>';
  }).join('') + '</div>';
}

function barRow(label, value, max, text, teal){
  var w = max ? Math.max(1, Math.min(100, (value/max)*100)) : 0;
  return '<tr><td>'+esc(label)+'</td><td style="width:45%"><div class="bar'+(teal?' teal':'')+
         '"><i style="width:'+w.toFixed(1)+'%"></i></div></td><td class="num">'+esc(text)+'</td></tr>';
}

function gapNote(gaps){
  if(!gaps || !gaps.length) return '';
  return gaps.map(function(g){
    return '<div class="gap"><b>'+esc(g.field)+' — no source in UBM</b>'+esc(g.note)+'</div>';
  }).join('');
}


/* ---- view header ----
   The prototype gives every screen a title, a one-line description and a freshness
   note. Reproduced here so the views read the same as the HTML. */
function viewHeader(title, blurb, note){
  return '<div class="title-row"><div><h1>'+esc(title)+'</h1><p>'+esc(blurb)+'</p></div>'+
         (note ? '<small>'+esc(note)+'</small>' : '')+'</div>';
}

/* ---- segmented toggle ----
   The prototype's Charges / Consumption / Variance style switches. State lives in
   this frame, and flipping it re-renders from the model already in hand, so no
   round trip to Appsmith and no query re-run. */
var TOGGLE = {};
function seg(group, options, current){
  if(TOGGLE[group] == null) TOGGLE[group] = current || options[0];
  return '<div class="seg" data-seg="'+esc(group)+'">' + options.map(function(o){
    return '<button data-seg-val="'+esc(o)+'"'+
           (TOGGLE[group]===o ? ' class="active"' : '')+'>'+esc(o)+'</button>';
  }).join('') + '</div>';
}
function segValue(group, fallback){
  return TOGGLE[group] != null ? TOGGLE[group] : fallback;
}


/* ---- tab row ----
   The prototype's Trends / Demand / Intensity / Weather style row. Shares the
   TOGGLE store with seg(), so a tab click re-renders the same way a switch does.
   In the prototype these are decorative; here they actually drive the view. */
function tabRow(group, options, current){
  if(TOGGLE[group] == null) TOGGLE[group] = current || options[0];
  return '<div class="tabs" data-seg="'+esc(group)+'">' + options.map(function(o){
    return '<button data-seg-val="'+esc(o)+'"'+
           (TOGGLE[group]===o ? ' class="active"' : '')+'>'+esc(o)+'</button>';
  }).join('') + '</div>';
}

/* A native select styled like the prototype's .btn dropdowns. */
function dropdown(group, options, current){
  if(TOGGLE[group] == null) TOGGLE[group] = current || options[0];
  return '<select class="btn" data-seg="'+esc(group)+'">' + options.map(function(o){
    return '<option'+(TOGGLE[group]===o ? ' selected' : '')+'>'+esc(o)+'</option>';
  }).join('') + '</select>';
}

function mount(render){
  function draw(){
    var m = (appsmith && appsmith.model) || {};
    try { document.getElementById('root').innerHTML = render(m); }
    catch(e){ document.getElementById('root').innerHTML =
      '<div class="empty">Could not render this view: '+esc(e.message)+'</div>'; }
  }

  /* One delegated listener for every segmented toggle on the view. */
  document.addEventListener('click', function(ev){
    var btn = ev.target.closest && ev.target.closest('[data-seg-val]');
    if(!btn) return;
    var box = btn.closest('[data-seg]');
    if(!box) return;
    TOGGLE[box.getAttribute('data-seg')] = btn.getAttribute('data-seg-val');
    draw();
  });

  document.addEventListener('change', function(ev){
    var sel = ev.target;
    if(!sel || sel.tagName !== 'SELECT' || !sel.getAttribute('data-seg')) return;
    TOGGLE[sel.getAttribute('data-seg')] = sel.value;
    draw();
  });

  draw();
  if(appsmith && typeof appsmith.onModelChange === 'function') appsmith.onModelChange(draw);
}

/* ---- Energy Performance ---- */
mount(function(m){
  if(m.empty || !m.kpis || !m.kpis.length)
    return '<div class="card empty">No billing rows for this customer and filter set.</div>';

  var out = viewHeader('Energy Performance',
    'Trends, demand, intensity and weather-normalized performance.') + kpiStrip(m.kpis);

  /* Trends / Demand / Intensity / Weather. The tab swaps the primary chart; the three
     cards underneath stay put, which is how the prototype lays the screen out. */
  var tab = segValue('en-tab', 'Trends');
  out += tabRow('en-tab', ['Trends','Demand','Intensity','Weather'], 'Trends');

  out += '<div class="grid two">';
  out += '<div class="card">' + primaryChart(m, tab) + '</div>';
  out += '<div class="card">' + driversPanel(m.drivers) + '</div>';
  out += '</div>';

  out += '<div class="grid three" style="margin-top:12px">';

  var bu = m.byUtility||{months:[],utilities:[],values:[]};
  out += '<div class="card"><h2>Monthly consumption by utility</h2>' +
    stackedBars(bu.months.map(function(x){return x.label;}),
      bu.utilities.map(function(u,i){ return {name:u, color:SERIES[i%SERIES.length], values:bu.values[i]||[]}; }), 175) +
    legend(bu.utilities.map(function(u,i){ return {name:u, color:SERIES[i%SERIES.length]}; })) + '</div>';

  var inten = (m.intensity||[]).slice(0,8);
  var mxI = inten.length ? inten[0].kbtuPerSqft : 0;
  out += '<div class="card"><h2>Location intensity</h2>' +
    (inten.length
      ? '<table>' + inten.map(function(r){
          return barRow(r.location, r.kbtuPerSqft, mxI, r.kbtuPerSqft.toFixed(1));
        }).join('') + '</table><div class="note">kBtu per square foot. Locations with no square footage on file are excluded.</div>'
      : '<div class="empty">No location has square footage on file</div>') + '</div>';

  var sc = m.scatter||[];
  out += '<div class="card"><h2>Weather sensitivity</h2>' +
    scatterChart(sc, fitFrom(m), 175, 'Total degree days', 'MMBtu') +
    '<div class="note">' + (m.drivers && m.drivers.available
      ? 'Consumption vs total degree days · R² = ' + m.drivers.r2.toFixed(2)
      : 'Consumption vs total degree days') + '</div></div>';

  out += '</div>';
  return out;
});

/* The scatter's trend line is the same fit the normalisation uses, rebuilt from the
   points so the chart and the number on the left cannot disagree. */
function fitFrom(m){
  var pts = m.scatter||[];
  var n = pts.length; if(n<2) return null;
  var sx=0, sy=0, sxy=0, sxx=0;
  pts.forEach(function(p){ sx+=p.x; sy+=p.y; sxy+=p.x*p.y; sxx+=p.x*p.x; });
  var d = n*sxx - sx*sx; if(!d) return null;
  var slope = (n*sxy - sx*sy)/d;
  return { slope: slope, intercept: (sy - slope*sx)/n };
}

function driversPanel(d){
  if(!d || !d.available)
    return '<h2>Performance drivers</h2><div class="empty">' +
           esc(d && d.reason ? d.reason : 'Weather normalisation unavailable') + '</div>';

  var below = d.residual < 0;
  var out = '<h2>Performance drivers</h2><small>Weather-normalised variance</small>' +
    '<b style="display:block;font-size:30px;color:'+(below?'var(--green)':'var(--red)')+';margin:8px 0">' +
      (below?'&darr; ':'&uarr; ') + pct(Math.abs(d.pct)) + '</b>' +
    '<p style="margin:0 0 10px">Actual consumption is ' + num(Math.abs(d.residual)) + ' MMBtu ' +
      (below?'below':'above') + ' the weather-normalised expectation.</p>';

  var locs = d.byLocation.slice(0,4).concat(d.byLocation.slice(-2));
  var seen = {};
  out += '<table>' + locs.filter(function(l){
      if(seen[l.location]) return false; seen[l.location]=1; return true;
    }).map(function(l){
      return '<tr><td>'+esc(l.location)+'</td><td class="num '+(l.residual<0?'down':'up')+'">' +
             (l.residual<0?'−':'+') + num(Math.abs(l.residual)) + ' MMBtu</td></tr>';
    }).join('') + '</table>' +
    '<div class="note">Fit R² ' + d.r2.toFixed(2) + ' over ' + d.monthly.length +
    ' months. Per-location figures apportion the portfolio residual by share of consumption.</div>';
  return out;
}


/* The tab's primary chart. Trends also carries the prototype's
   Monthly / Annual / Per sq ft switch. */
function primaryChart(m, tab){
  var t = m.trend || [];

  if(tab === 'Demand'){
    var d = m.demand || [];
    if(!d.length) return '<h2>Monthly electric demand</h2>' +
      '<div class="empty">No demand data. This chart reads bill line items, not the monthly rollup.</div>';
    return '<div class="chart-head"><h2>Monthly electric demand</h2>' +
      seg('en-dem', ['Demand','Load factor'], 'Demand') + '</div>' +
      (segValue('en-dem','Demand') === 'Load factor'
        ? lineChart(d.map(function(p){return p.label;}),
            [{name:'Load factor', color:C.purple, values:d.map(function(p){return p.loadFactor;})}]) +
          '<div class="note">Average load factor per month. Months with no reading are gaps, not zeroes.</div>'
        : lineChart(d.map(function(p){return p.label;}),
            [{name:'Peak demand', color:C.purple, values:d.map(function(p){return p.demand;})}]) +
          '<div class="note">Highest billed demand in each month, in kW.</div>');
  }

  if(tab === 'Intensity'){
    var i = m.intensity || [];
    if(!i.length) return '<h2>Energy intensity</h2>' +
      '<div class="empty">No location has square footage on file</div>';
    var top = i.slice(0, 14), mx = top[0].kbtuPerSqft;
    return '<h2>Energy intensity by location</h2>' +
      stackedBars(top.map(function(r){ return r.location.slice(0,14); }),
        [{name:'kBtu/sq ft', color:C.teal, values:top.map(function(r){ return r.kbtuPerSqft; })}]) +
      '<div class="note">kBtu per square foot. Locations with no square footage are excluded, not counted as zero.</div>';
  }

  if(tab === 'Weather'){
    var sc = m.scatter || [];
    return '<h2>Consumption against degree days</h2>' +
      lineChart(sc.map(function(p){return p.label;}), [
        {name:'MMBtu',       color:C.blue, values:sc.map(function(p){return p.y;})},
        {name:'Degree days', color:C.amber, values:sc.map(function(p){return p.x;})}
      ]) +
      legend([{name:'MMBtu',color:C.blue},{name:'Degree days',color:C.amber}]) +
      '<div class="note">Degree days come from the monthly usage rows, one reading per month.</div>';
  }

  /* Trends */
  var mode = segValue('en-mode', 'Monthly');
  var head = '<div class="chart-head"><h2>Monthly consumption</h2>' +
             seg('en-mode', ['Monthly','Annual','Per sq ft'], 'Monthly') + '</div>';

  if(mode === 'Annual'){
    var byYear = {};
    t.forEach(function(p){
      var y = p.month.slice(0,4);
      byYear[y] = (byYear[y] || 0) + (p.mmbtu || 0);
    });
    var ys = Object.keys(byYear).sort();
    return head + stackedBars(ys, [{name:'MMBtu', color:C.blue, values:ys.map(function(y){return byYear[y];})}]) +
      '<div class="note">Calendar-year totals in MMBtu.</div>';
  }

  if(mode === 'Per sq ft'){
    var sqft = m.totalSqft || 0;
    if(!sqft) return head + '<div class="empty">No square footage on file for these locations</div>';
    return head + lineChart(t.map(function(p){return p.label;}),
      [{name:'kBtu/sq ft', color:C.teal, values:t.map(function(p){ return (p.mmbtu*1000)/sqft; })}]) +
      '<div class="note">Monthly kBtu per square foot, across locations that have square footage on file.</div>';
  }

  return head + lineChart(t.map(function(p){return p.label;}),
      [{name:'Current year', color:C.blue, values:t.map(function(p){return p.mmbtu;})},
       {name:'Prior year',   color:C.teal, dash:true, values:t.map(function(p){return p.priorMmbtu;})}]) +
    legend([{name:'Current year',color:C.blue},{name:'Prior year',color:C.teal}]) +
    '<div class="note">MMBtu, so electricity and gas can be added together.</div>';
}
